import {currentPlan} from './life.js';
import {clamp,dangerAt} from './city.js';
export const actionNames=['Eating','Resting','Socializing','Working','Learning','Exploring','Healing','Seeking shelter'];
export const inputNames=['Hunger','Fatigue','Loneliness','Money need','Curiosity','Health risk','Local danger','Night','Food supply','Rain','Temperature','Empathy','Ambition','Caution','Crowding','Home distance','Familiarity','Previous reward','Attachment','Power'];
const N=128,A=8;
function rng(seed){return ()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296}}
const wiringCache=new Map();
function wiring(id){if(wiringCache.has(id))return wiringCache.get(id);const r=rng(id+4337);const w={projection:Array.from({length:32},()=>Array.from({length:20},()=>r()*2-1)),sparse:Array.from({length:N},()=>Array.from({length:6},()=>Math.floor(r()*32))),recurrent:Array.from({length:16},()=>Array.from({length:16},()=> (r()-.5)*.3))};wiringCache.set(id,w);return w}
export function createBrain(id,legacy){const r=rng(id+9201);return {version:3,weights:Array.from({length:A},()=>Array.from({length:N},()=> (r()-.5)*.05)),longWeights:Array.from({length:A},()=>Array(N).fill(0)),context:Array(16).fill(0),updates:0,totalUpdates:legacy?.updates||0,reward:0,predictionError:0,baseline:0,history:[],episodes:[],places:{},lessons:[],legacy:legacy?{updates:legacy.updates||0,lastReward:legacy.reward||0,architecture:'12–10–8–6',weights:legacy.weights,biases:legacy.biases}:null,trace:null}}
export function ensureBrain(c){if(c.brain?.version!==3)c.brain=createBrain(c.id,c.brain);return c.brain}
export function infer(c,sim,nearby=0){const b=ensureBrain(c),w=wiring(c.id),night=sim.light==='Night'||(sim.light==='Cycle'&&(sim.day%1<.25||sim.day%1>.8));const home=sim.world.parcels.find(p=>p.id===c.home);const inputs=[1-c.hunger/100,1-c.energy/100,1-c.social/100,1-Math.min(c.wealth/180,1),c.curiosity/100,1-c.health/100,dangerAt(sim,c.x,c.z),night?1:0,Math.min(sim.food/100,1),sim.weather==='Clear'?0:1,Math.abs(sim.temperature-22)/25,c.empathy/100,c.ambition/100,c.caution/100,Math.min(nearby/8,1),home?Math.min(Math.hypot(c.x-home.x,c.z-home.z)/100,1):0,Math.min(Object.keys(b.places).length/15,1),clamp((b.reward+1)/2,0,1),c.partner===null?0:1,sim.power/100].map(v=>clamp(v,0,1));
 const projection=w.projection.map(row=>Math.tanh(row.reduce((s,v,i)=>s+v*inputs[i],0)/3));
 const raw=w.sparse.map((indices,j)=>indices.reduce((s,i)=>s+projection[i],0)/6+b.context[j%16]*.12);
 const active=raw.map((v,i)=>({v,i})).sort((a,b)=>b.v-a.v).slice(0,12);const sparse=Array(N).fill(0);for(const {v,i}of active)sparse[i]=.5+.5*Math.tanh(v);
 b.context=b.context.map((v,j)=>Math.tanh(v*.68+projection[j]*.22+w.recurrent[j].reduce((s,a,i)=>s+a*b.context[i],0)*.1));
 const learned=b.weights.map((row,a)=>row.reduce((s,v,j)=>s+(v+b.longWeights[a][j]) * sparse[j],0)/3);
 const drives=[inputs[0]*4,inputs[1]*3.5+inputs[7]*.45,inputs[2]*3,inputs[3]*.8+c.ambition/160,.3+c.curiosity/200, .25+c.curiosity/160,inputs[5]*4,inputs[6]*5];
 const plan=currentPlan(c,sim);const q=drives.map((v,i)=>v+learned[i]+b.context[i]*.1+(actionNames[i]===plan.action ? .55 : 0));const allowed=[sim.food>0,true,true,c.age>=18,true,true,c.health<98,inputs[6]>.12||sim.weather==='Storm'];
 const max=Math.max(...q.filter((v,i)=>allowed[i]));let probabilities=q.map((v,i)=>allowed[i]?Math.exp((v-max)*2.3):0);const sum=probabilities.reduce((s,v)=>s+v,0);probabilities=probabilities.map(v=>v/sum);
 // Small deterministic exploration probability: repeatable per citizen and decision.
 let chosen=probabilities.indexOf(Math.max(...probabilities));if((sim.tick+c.id*13)%29===0){const r=rng(sim.tick+c.id*41)();let total=0;chosen=probabilities.findIndex(p=>(total+=p)>r);if(chosen<0)chosen=0}
 let override='';if(c.hunger<16&&allowed[0]){chosen=0;override='Critical hunger'}else if(c.energy<12){chosen=1;override='Critical fatigue'}else if(inputs[6]>.75){chosen=7;override='Immediate danger'}
 const trace={inputs,projection,sparse,context:[...b.context],probabilities,q,chosen,allowed,override,active:active.map(v=>v.i),tick:sim.tick};b.trace=trace;return trace}
export function learn(c,trace,reward,episode){const b=ensureBrain(c);const prediction=b.weights[trace.chosen].reduce((s,v,j)=>s+v*trace.sparse[j],0)/3;const error=clamp(reward-prediction,-1,1);for(let j=0;j<N;j++){b.weights[trace.chosen][j]=clamp(b.weights[trace.chosen][j]+.08*error*trace.sparse[j],-2,2)}b.reward=reward;b.predictionError=error;b.baseline=b.baseline*.9+reward*.1;b.updates++;b.totalUpdates++;b.history.unshift({action:actionNames[trace.chosen],reward});b.history=b.history.slice(0,8);
 b.episodes.unshift({...episode,action:actionNames[trace.chosen],reward,error,activeCells:trace.active});b.episodes=b.episodes.slice(0,100);
 if(episode.placeId!==undefined){const id=episode.placeId,old=b.places[id]||{visits:0,value:0,name:episode.place};old.visits++;old.value=.7*old.value+.3*reward;b.places[id]=old}
 if(b.updates%8===0){for(let a=0;a<A;a++)for(let j=0;j<N;j++){b.longWeights[a][j]=b.longWeights[a][j]*.98+b.weights[a][j]*.02;b.weights[a][j]*=.995}b.lessons.unshift({day:episode.day,text:`${episode.place}: ${reward>=0?'helpful':'costly'} for ${actionNames[trace.chosen].toLowerCase()}. Reinforced across ${b.updates} experiences.`});b.lessons=b.lessons.slice(0,24)}
}
export function neuralView(c){const b=ensureBrain(c),t=b.trace;if(!t)return '<p>Gathering sensory signals for the next decision…</p>';let svg='<svg viewBox="0 0 354 310" role="img" aria-label="Fly-inspired circuit: 20 senses, 32 projection neurons, 128 sparse memory cells, 16 recurrent context neurons and 8 action outputs">';const xs=[17,81,177,273,335],counts=[20,32,128,16,8],values=[t.inputs,t.projection,t.sparse,t.context,t.probabilities];const point=(l,i)=>({x:xs[l]+(l===2?(i%8-3.5)*9:0),y:38+(l===2?Math.floor(i/8)*15:i*235/(counts[l]-1))});for(let l=0;l<4;l++)for(let i=0;i<counts[l];i++){if(l===2&&!t.sparse[i])continue;for(let j=0;j<3;j++){const a=point(l,i),v=point(l+1,(i*7+j*11)%counts[l+1]);svg+=`<path d="M${a.x},${a.y} L${v.x},${v.y}" stroke="${l===2?'#cf8097':'#5baba3'}" opacity="${values[l][i]>.3?.35:.09}" fill="none"/>`}}for(let l=0;l<5;l++){svg+=`<text x="${xs[l]}" y="16" text-anchor="middle">${['20 IN','32 PN','128 KC','16 CTX','8 ACT'][l]}</text>`;for(let i=0;i<counts[l];i++){const p=point(l,i),a=values[l][i];svg+=`<circle cx="${p.x}" cy="${p.y}" r="${l===2?2.8:l===4?5:3}" fill="${a>.3?'#f3b952':a>0?'#68c9b3':'#d5e1de'}" stroke="#658c97" stroke-width=".5"><title>${l===0?inputNames[i]:l===4?actionNames[i]:`Layer ${l} cell ${i+1}`}: ${a.toFixed(3)}</title></circle>`}}svg+='<path d="M280 285 Q215 317 163 284" fill="none" stroke="#d8789a" stroke-dasharray="3 3"/><text x="215" y="304" text-anchor="middle">REWARD → MEMORY PLASTICITY</text></svg>';
return `<div class="neural-meta">MUSHROOM-BODY MODEL <span>${b.updates} experiences</span></div>${svg}<div class="net-legend"><span>12 / 128 memory cells active</span><span>Sampled connections shown</span></div><div class="signals">${inputNames.map((name,i)=>`<span>${name}<b>${Math.round(t.inputs[i]*100)}%</b></span>`).join('')}</div><h3>ACTION POLICY ${t.override?'· SURVIVAL OVERRIDE':''}</h3>${actionNames.map((name,i)=>`<div class="prob ${i===t.chosen?'chosen':''}"><span>${i===t.chosen?'▶ ':''}${name}</span><meter min="0" max="1" value="${t.probabilities[i]}"></meter><b>${Math.round(t.probabilities[i]*100)}%</b></div>`).join('')}<div class="reward">REWARD <b>${b.reward.toFixed(3)}</b> · PREDICTION ERROR <b>${b.predictionError.toFixed(3)}</b></div><p class="brain-note">Sparse sensory coding + recurrent context + short/long-term associative weights. Learning occurs after a completed or failed activity. A simplified fly-inspired model, not a biological brain. <a target="_blank" rel="noopener" href="https://www.janelia.org/lab/aso-lab/our-research">Research reference ↗</a></p>`}
